      "name": "Finsupp.sum_zero_index",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] {h : α → M → N} : Finsupp.sum 0 h = 0",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_fun_zero",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] (f : α →₀ M) : (f.sum fun x x_1 => 0) = 0",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_single_index",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] {a : α} {b : M} {h : α → M → N} (h_zero : h a 0 = 0) : (fun₀ | a => b).sum h = h a b",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_fintype",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] [Fintype α] (f : α →₀ M) (g : α → M → N) (h : ∀ (i : α), g i 0 = 0) : f.sum g = ∑ i, g i (f i)",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.onFinset_sum",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] {s : Finset α} {f : α → M} {g : α → M → N} (hf : ∀ (a : α), f a ≠ 0 → a ∈ s) (hg : ∀ (a : α), g a 0 = 0) : (Finsupp.onFinset s f hf).sum g = ∑ a ∈ s, g a (f a)",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_indicator_index",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] {s : Finset α} (f : α → M) {h : α → M → N} (h_zero : ∀ a ∈ s, h a 0 = 0) : (Finsupp.indicator s fun x x_1 => f x).sum h = ∑ x ∈ s, h x (f x)",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_mapRange_index",
      "type": " {α : Type u_1} {M : Type u_8} {M' : Type u_9} {N : Type u_10} [Zero M] [Zero M'] [AddCommMonoid N] {f : M → M'} {hf : f 0 = 0} {g : α →₀ M} {h : α → M' → N} (h0 : ∀ (a : α), h a 0 = 0) : (Finsupp.mapRange f hf g).sum h = g.sum fun a b => h a (f b)",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "AddSubmonoidClass.finsuppSum_mem",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] {S : Type u_16} [SetLike S N] [AddSubmonoidClass S N] (s : S) (f : α →₀ M) (g : α → M → N) (h : ∀ (c : α), f c ≠ 0 → g c (f c) ∈ s) : f.sum g ∈ s",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_ite_self_eq",
      "type": " {α : Type u_1} [DecidableEq α] {N : Type u_16} [AddCommMonoid N] (f : α →₀ N) (a : α) : (f.sum fun x v => if a = x then v else 0) = f a",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_ite_self_eq'",
      "type": " {α : Type u_1} [DecidableEq α] {N : Type u_16} [AddCommMonoid N] (f : α →₀ N) (a : α) : (f.sum fun x v => if x = a then v else 0) = f a",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.add_sum_erase'",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] (f : α →₀ M) (y : α) (g : α → M → N) (hg : ∀ (i : α), g i 0 = 0) : g y (f y) + (Finsupp.erase y f).sum g = f.sum g",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_onFinset",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] (s : Finset α) (f : α → M) (hf : ∀ (a : α), f a ≠ 0 → a ∈ s) (g : α → M → N) (hg : ∀ i ∈ s, g i 0 = 0) : (Finsupp.onFinset s f hf).sum g = ∑ a ∈ s, g a (f a)",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    }
  ]
}
